-- READ-ONLY main-backend alignment preflight. Execute only with explicit project_id
-- ufehcfrlygqvminfjumf. No baseline, data, settings or schema writes.
begin read only;
set local search_path='';
do $alignment_preflight$
declare actual text;
begin
 select md5(row_to_json(q)::text) into actual from (select jsonb_build_object(
'tables',(select jsonb_agg(jsonb_build_object('oid',c.oid,'schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'persistence',c.relpersistence,'options',c.reloptions,'replica_identity',c.relreplident,'access_method',am.amname) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace left join pg_am am on am.oid=c.relam where n.nspname in ('public','private') and c.relkind in ('r','p','v','m','S','f')),
'columns',(select jsonb_agg(jsonb_build_object('table',a.attrelid,'number',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'collation',case when a.attcollation<>t.typcollation then co.collname end,'collation_schema',case when a.attcollation<>t.typcollation then cn.nspname end,'acl',a.attacl) order by a.attrelid,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace join pg_type t on t.oid=a.atttypid left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum left join pg_collation co on co.oid=a.attcollation left join pg_namespace cn on cn.oid=co.collnamespace where n.nspname in ('public','private') and c.relkind in ('r','p','v','m','f') and a.attnum>0 and not a.attisdropped),
'constraints',(select jsonb_agg(jsonb_build_object('table',co.conrelid,'name',co.conname,'type',co.contype,'validated',co.convalidated,'def',pg_get_constraintdef(co.oid,true),'parent',co.conparentid,'index',co.conindid) order by co.conrelid,co.contype,co.conname) from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')),
'indexes',(select jsonb_agg(jsonb_build_object('table',i.indrelid,'oid',i.indexrelid,'name',ic.relname,'def',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'primary',i.indisprimary,'clustered',i.indisclustered,'replica_identity',i.indisreplident,'constraint',co.conname) order by i.indrelid,ic.relname) from pg_index i join pg_class c on c.oid=i.indrelid join pg_namespace n on n.oid=c.relnamespace join pg_class ic on ic.oid=i.indexrelid left join pg_constraint co on co.conindid=i.indexrelid and co.contype in ('p','u','x') where n.nspname in ('public','private')),
'types',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'kind',t.typtype,'relation',t.typrelid,'base_type',format_type(t.typbasetype,t.typtypmod),'default',t.typdefault,'not_null',t.typnotnull,'owner',pg_get_userbyid(t.typowner),'enum_values',(select jsonb_agg(e.enumlabel order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid)) order by n.nspname,t.typname) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','private') and t.typelem=0 and t.typrelid=0 and not exists(select 1 from pg_depend dep where dep.classid='pg_catalog.pg_type'::regclass and dep.objid=t.oid and dep.deptype='e')),
'inheritance',(select jsonb_agg(jsonb_build_object('child',i.inhrelid,'parent',i.inhparent)) from pg_inherits i join pg_class c on c.oid=i.inhrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private'))
) as structure) q;
 if actual is distinct from 'e51942c5f193d472632799bd677be230' then raise exception 'Production catalog drift: structure'; end if;
 select md5(row_to_json(q)::text) into actual from (select coalesce(jsonb_agg(jsonb_build_object('oid',p.oid,'schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'kind',p.prokind,'language',l.lanname,'definer',p.prosecdef,'config',p.proconfig,'sql_body',p.prosqlbody is not null,'definition',pg_get_functiondef(p.oid)) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]'::jsonb) as functions from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('public','private') and p.prokind in ('f','p') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')) q;
 if actual is distinct from 'ad0354f48bc1966b63afd838c9540b9a' then raise exception 'Production catalog drift: functions'; end if;
 select md5(row_to_json(q)::text) into actual from (select jsonb_build_object(
'policies',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',pol.polname,'permissive',pol.polpermissive,'command',pol.polcmd,'roles',(select jsonb_agg(case when r=0 then 'PUBLIC' else pg_get_userbyid(r) end order by r) from unnest(pol.polroles) r),'using',pg_get_expr(pol.polqual,pol.polrelid),'check',pg_get_expr(pol.polwithcheck,pol.polrelid)) order by n.nspname,c.relname,pol.polname) from pg_policy pol join pg_class c on c.oid=pol.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','storage','auth')),
'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'function',t.tgfoid,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid join pg_namespace fn on fn.oid=p.pronamespace where not t.tgisinternal and (n.nspname in ('public','private') or fn.nspname in ('public','private'))),
'rules',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',r.rulename,'definition',pg_get_ruledef(r.oid,true)) order by n.nspname,c.relname,r.rulename) from pg_rewrite r join pg_class c on c.oid=r.ev_class join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and r.rulename<>'_RETURN'),
'publications',(select jsonb_agg(jsonb_build_object('name',p.pubname,'schema',n.nspname,'table',c.relname,'columns',pr.prattrs,'filter',pg_get_expr(pr.prqual,pr.prrelid)) order by p.pubname,n.nspname,c.relname) from pg_publication_rel pr join pg_publication p on p.oid=pr.prpubid join pg_class c on c.oid=pr.prrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')),
'event_triggers',(select jsonb_agg(jsonb_build_object('name',e.evtname,'event',e.evtevent,'enabled',e.evtenabled,'function',e.evtfoid)) from pg_event_trigger e join pg_proc p on p.oid=e.evtfoid join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private'))
) as security) q;
 if actual is distinct from '4ec3ac92fbe688620546bc49965fa8aa' then raise exception 'Production catalog drift: security'; end if;
 select md5(row_to_json(q)::text) into actual from (select jsonb_build_object(
'schemas',(select jsonb_agg(jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),'privileges',(select jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)) from aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a)) order by n.nspname) from pg_namespace n where n.nspname in ('public','private')),
'tables',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'privileges',(select jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)) from aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S' then 's'::"char" else 'r'::"char" end,c.relowner))) a)) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind in ('r','p','v','m','S')),
'columns',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'column',at.attname,'privileges',(select jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)) from aclexplode(at.attacl) a))) from pg_attribute at join pg_class c on c.oid=at.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and at.attnum>0 and not at.attisdropped and at.attacl is not null),
'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'privileges',(select jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
'defaults',(select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'kind',d.defaclobjtype,'privileges',(select jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)) from aclexplode(d.defaclacl) a)) order by d.defaclrole,d.defaclnamespace,d.defaclobjtype) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in ('public','private') or d.defaclnamespace=0)
) as acl) q;
 if actual is distinct from '2d80a140cf56b9cd29fd5d35a490ee68' then raise exception 'Production catalog drift: acl'; end if;
 select md5(row_to_json(q)::text) into actual from (select jsonb_build_object(
'external_constraints',(select jsonb_agg(jsonb_build_object('source',n.nspname||'.'||c.relname,'name',co.conname,'definition',pg_get_constraintdef(co.oid,true),'target',rn.nspname||'.'||rc.relname)) from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace join pg_class rc on rc.oid=co.confrelid join pg_namespace rn on rn.oid=rc.relnamespace where co.contype='f' and (n.nspname in ('public','private') or rn.nspname in ('public','private')) and n.nspname<>rn.nspname and (n.nspname not in ('public','private') or rn.nspname not in ('public','private'))),
'external_object_dependencies',(select jsonb_agg(jsonb_build_object('object',pg_describe_object(d.classid,d.objid,d.objsubid),'depends_on',pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid),'dependency_type',d.deptype)) from pg_depend d where d.classid in ('pg_proc'::regclass,'pg_class'::regclass,'pg_attrdef'::regclass,'pg_constraint'::regclass,'pg_policy'::regclass) and ((d.classid='pg_proc'::regclass and d.objid in(select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private'))) or (d.classid='pg_class'::regclass and d.objid in(select c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')))) and d.refclassid in ('pg_proc'::regclass,'pg_class'::regclass,'pg_type'::regclass) and not (d.refclassid='pg_type'::regclass and d.refobjid<16384)),
'custom_operators',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',o.oprname)) from pg_operator o join pg_namespace n on n.oid=o.oprnamespace where n.nspname in ('public','private') and not exists(select 1 from pg_depend d where d.classid='pg_operator'::regclass and d.objid=o.oid and d.deptype='e')),
'custom_casts',(select jsonb_agg(jsonb_build_object('from',format_type(c.castsource,null),'to',format_type(c.casttarget,null))) from pg_cast c join pg_type t on t.oid=c.castsource join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','private')),
'custom_collations',(select jsonb_agg(collname) from pg_collation c join pg_namespace n on n.oid=c.collnamespace where n.nspname in ('public','private')),
'custom_aggregates',(select jsonb_agg(p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prokind='a'),
'publication_settings',(select jsonb_agg(jsonb_build_object('name',pubname,'all_tables',puballtables,'insert',pubinsert,'update',pubupdate,'delete',pubdelete,'truncate',pubtruncate)) from pg_publication where pubname in(select p.pubname from pg_publication_rel r join pg_publication p on p.oid=r.prpubid join pg_class c on c.oid=r.prrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')))
) as dependencies) q;
 if actual is distinct from '5989a20da7f83e86efaa37c553fd8eaa' then raise exception 'Production catalog drift: dependencies'; end if;
 select md5(row_to_json(q)::text) into actual from (select jsonb_build_object(
'object_descriptions',(select jsonb_agg(jsonb_build_object('object',pg_describe_object(d.classoid,d.objoid,d.objsubid),'comment',d.description)) from pg_description d where (d.classoid='pg_class'::regclass and d.objoid in(select c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private'))) or (d.classoid='pg_proc'::regclass and d.objoid in(select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private'))) or (d.classoid='pg_constraint'::regclass and d.objoid in(select co.oid from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')))),
'managed_auth_references',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull)) from pg_attribute a where a.attrelid='auth.users'::regclass and a.attnum>0 and not a.attisdropped and a.attname in ('id','email','role','aud','encrypted_password','created_at','updated_at')),
'extension_dependencies',(select jsonb_agg(jsonb_build_object('object',pg_describe_object(d.classid,d.objid,d.objsubid),'extension',e.extname)) from pg_depend d join pg_extension e on d.refclassid='pg_extension'::regclass and e.oid=d.refobjid where (d.classid='pg_proc'::regclass and d.objid in(select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private'))) or (d.classid='pg_type'::regclass and d.objid in(select t.oid from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','private')))),
'unusual_column_metadata',(select jsonb_agg(jsonb_build_object('table',a.attrelid::regclass::text,'column',a.attname,'storage',a.attstorage,'compression',a.attcompression,'statistics',a.attstattarget,'options',a.attoptions,'missing_value_present',a.atthasmissing)) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace join pg_type t on t.oid=a.atttypid where n.nspname in ('public','private') and a.attnum>0 and not a.attisdropped and (a.attstorage<>t.typstorage or a.attcompression<>'' or a.attstattarget<>-1 or a.attoptions is not null)),
'statistics_objects',(select jsonb_agg(s.stxname) from pg_statistic_ext s join pg_namespace n on n.oid=s.stxnamespace where n.nspname in ('public','private')),
'managed_schema_functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='auth' and p.proname in ('uid','jwt','role')) or (n.nspname='storage' and p.proname in ('foldername','filename','extension')))
) as extras) q;
 if actual is distinct from '6817ab173cda8900cefd8129527e4892' then raise exception 'Production catalog drift: extras'; end if;
 if (select array_agg(version order by version)::text[] from supabase_migrations.schema_migrations) is distinct from array['20260819180000','20260823100000','20261002014604','20261002015419','20261002123039','20261002124738','20261003224001','20261004025120','20261005004045']::text[] then raise exception 'Migration history changed'; end if;
 if exists(select 1 from public.products where nullif(btrim(barcode),'') is not null group by business_id,btrim(barcode) having count(*)>1) or exists(select 1 from public.products where nullif(btrim(sku),'') is not null group by business_id,btrim(sku) having count(*)>1) then raise exception 'Resolve duplicate manufacturer barcode/SKU before approval'; end if;
end $alignment_preflight$;
select 'MAIN_BACKEND_ALIGNMENT_PREFLIGHT_PASSED' as result;
commit;

